// StarClaw autonomous agent – fixes verifyBundle to reject duplicated‑last‑event bundles
// and adds a vitest test confirming the fix.

const path = require('path');

async function execute() {
  // ---------- 1. Patch verifyBundle in audit-chain.ts ----------
  const auditChainPath = './mnemopay-sdk/src/governance/audit-chain.ts';
  const auditRes = await tools.readFile({ path: auditChainPath });
  if (auditRes.truncated) {
    console.log('⚠️ audit-chain.ts is too large to read completely.');
    return { success: false, reason: 'file truncated' };
  }
  const auditContent = auditRes.content;

  // Find the exact line that starts the verifyBundle function.
  const verifyLineMatch = auditContent.match(/^.*function\s+verifyBundle\s*\([^)]*\)\s*{.*$/m);
  if (!verifyLineMatch) {
    console.log('❌ Could not locate verifyBundle definition.');
    return { success: false, reason: 'verifyBundle not found' };
  }
  const originalVerifyLine = verifyLineMatch[0];

  // Build the code snippet that will be inserted right after the opening brace.
  const insertion = `
    // ★★ START – duplicate‑last‑event guard (added by StarClaw) ★★
    // If the bundle has an odd number of events, the Merkle tree pads by
    // repeating the last leaf.  A duplicated last event would therefore have
    // the same sequence number as its predecessor – this is illegal.
    if (bundle.events.length % 2 === 1) {
      const n = bundle.events.length;
      const last = bundle.events[n - 1];
      const secondLast = bundle.events[n - 2];
      if (last.sequence === secondLast.sequence) {
        throw new Error('verifyBundle: duplicated last event detected');
      }
    }
    // ★★ END – duplicate‑last‑event guard ★★`;

  // Prepare the replacement: original line + insertion (preserving original line).
  const newVerifyLine = `${originalVerifyLine}${insertion}`;

  // Apply the edit.
  await tools.editFile({
    path: auditChainPath,
    find: originalVerifyLine,
    replace: newVerifyLine,
    // we expect exactly one replacement
    expectCount: 1,
  });

  // ---------- 2. Add a vitest test ----------
  const testPath = './mnemopay-sdk/tests/audit-chain.test.ts';
  const testRes = await tools.readFile({ path: testPath });
  if (testRes.truncated) {
    console.log('⚠️ audit-chain.test.ts is too large to read completely.');
    return { success: false, reason: 'test file truncated' };
  }
  const testContent = testRes.content;

  // Locate the final closing brace of the outermost describe block.
  // We'll look for a line that is exactly "});" at the end of the file.
  const closingMatch = testContent.match(/^(\s*)\}\);\s*$/m);
  if (!closingMatch) {
    console.log('❌ Could not locate the closing "});" of the test suite.');
    return { success: false, reason: 'test suite closing not found' };
  }
  const indent = closingMatch[1] || '';

  // New test code (uses the public SDK API).
  const newTest = `
${indent}it('rejects a bundle with a duplicated last event when count is odd', async () => {
${indent}  // Build a valid bundle first.
${indent}  const { AuditChain, ChainEvent } = require('@mnemopay/sdk');
${indent}  const chain = new AuditChain();
${indent}  // Add three events (odd count).
${indent}  chain.appendEvent({ sequence: 1, data: 'a' } as ChainEvent);
${indent}  chain.appendEvent({ sequence: 2, data: 'b' } as ChainEvent);
${indent}  chain.appendEvent({ sequence: 3, data: 'c' } as ChainEvent);
${indent}  const goodBundle = chain.exportBundle();

${indent}  // Verify that the good bundle passes.
${indent}  expect(() => AuditChain.verifyBundle(goodBundle)).not.toThrow();

${indent}  // Tamper: duplicate the last event.
${indent}  const badBundle = { ...goodBundle, events: [...goodBundle.events, goodBundle.events[goodBundle.events.length - 1]] };

${indent}  // The verification should now throw.
${indent}  expect(() => AuditChain.verifyBundle(badBundle)).toThrow(/duplicated last event/);
${indent}});`;

  // Insert the new test just before the final "});"
  const newTestContent = testContent.replace(/^(\s*)\}\);\s*$/m, `${newTest}\n$1});`);

  // Write the updated test file.
  await tools.writeFile({ path: testPath, content: newTestContent });

  // ---------- 3. Done ----------
  console.log('✅ verifyBundle patched and new test added successfully.');
  return { success: true };
}

module.exports = { execute };

// StarClaw autonomous agent
// This script reads the source and test files for the @mnemopay/sdk package,
// patches verifyBundle() to reject bundles that duplicate the last event,
// and adds a vitest test that ensures the new check works.

const path = require('path');

async function execute() {
  // ---------- 1. Locate the files ----------
  const auditPath = './mnemopay-sdk/src/governance/audit-chain.ts';
  const testPath = './mnemopay-sdk/tests/audit-chain.test.ts';

  // ---------- 2. Read the current source ----------
  const auditFile = await tools.readFile({ path: auditPath });
  if (auditFile.truncated) {
    console.log('⚠️ audit-chain.ts is larger than the allowed read size.');
    return;
  }
  let auditContent = auditFile.content;

  // ---------- 3. Insert sequence‑validation into verifyBundle ----------
  // Find the start of the verifyBundle function.
  const verifyFnIdx = auditContent.indexOf('function verifyBundle');
  if (verifyFnIdx === -1) {
    console.log('❌ Could not locate verifyBundle() in audit-chain.ts');
    return;
  }

  // Find the opening brace of the function.
  const braceIdx = auditContent.indexOf('{', verifyFnIdx);
  if (braceIdx === -1) {
    console.log('❌ Malformed verifyBundle() – no opening brace.');
    return;
  }

  // Locate the line where the events array is extracted from the bundle.
  const eventsLineMatch = auditContent.slice(braceIdx).match(/const\s+events\s*=\s*bundle\.events\s*;/);
  if (!eventsLineMatch) {
    console.log('❌ Could not find the "const events = bundle.events;" line.');
    return;
  }

  // Compute insertion point: right after the events line.
  const eventsLineStart = auditContent.indexOf(eventsLineMatch[0], braceIdx) + eventsLineMatch[0].length;

  const sequenceCheck = `\n  // --- BEGIN sequence validation (added by StarClaw) ---\n` +
    `  // Ensure that event sequence numbers are strictly consecutive.\n` +
    `  for (let i = 1; i < events.length; i++) {\n` +
    `    if (events[i].sequence !== events[i - 1].sequence + 1) {\n` +
    `      throw new Error('Invalid event sequence: duplicate or out‑of‑order event');\n` +
    `    }\n` +
    `  }\n` +
    `  // --- END sequence validation ---\n`;

  // Insert the check.
  auditContent =
    auditContent.slice(0, eventsLineStart) +
    sequenceCheck +
    auditContent.slice(eventsLineStart);

  // Write the patched source back.
  await tools.writeFile({ path: auditPath, content: auditContent });

  // ---------- 4. Read the existing test file ----------
  const testFile = await tools.readFile({ path: testPath });
  if (testFile.truncated) {
    console.log('⚠️ audit-chain.test.ts is larger than the allowed read size.');
    return;
  }
  let testContent = testFile.content;

  // ---------- 5. Append a new vitest test ----------
  // Determine whether a helper called makeValidBundle (or similar) already exists.
  const hasHelper = /makeValidBundle|createValidBundle|validBundle/.test(testContent);

  // Build the test code.
  const newTest = `\n` +
    `test('verifyBundle rejects duplicated last event', async () => {\n` +
    `  // Obtain a known‑good bundle using the project's test helpers if available.\n` +
    (hasHelper
      ? `  const bundle = await makeValidBundle();\n`
      : `  // Fallback: construct a minimal valid bundle using the public API.\n` +
        `  const { AuditChain } = require('../src/governance/audit-chain');\n` +
        `  const chain = new AuditChain();\n` +
        `  // Add three dummy events (odd count) – the concrete shape of a ChainEvent\n` +
        `  // is not important for the sequence check; we only need the sequence field.\n` +
        `  chain.addEvent({ sequence: 1, payload: {} });\n` +
        `  chain.addEvent({ sequence: 2, payload: {} });\n` +
        `  chain.addEvent({ sequence: 3, payload: {} });\n` +
        `  const bundle = await chain.finalize();\n`) +
    `  // Duplicate the last event.\n` +
    `  const dup = bundle.events[bundle.events.length - 1];\n` +
    `  const tampered = { ...bundle, events: [...bundle.events, dup] };\n` +
    `  await expect(verifyBundle(tampered)).rejects.toThrow();\n` +
    `});\n`;

  // Append the test at the end of the file (before any trailing whitespace).
  testContent = testContent.replace(/\s*$/g, '') + newTest + '\n';

  // Write the updated test file.
  await tools.writeFile({ path: testPath, content: testContent });

  // ---------- 6. Done ----------
  console.log('✅ Patch applied: verifyBundle now validates event sequences, and a new test has been added.');
  console.log('Run the test suite (e.g., `npm test` or `vitest`) to confirm the fix.');
}

module.exports = { execute };
